        # DP[i][S]: Number of ways to assign p(1), ..., p(i-1) such that S is the usage mask for {i, i+1, i+2, i+3}
        # We use 1-based indexing for i. Size N+2 to allow DP[N+1].
        DP = [[0] * MAX_STATE for _ in range(N + 2)]

        # --- Base Case: p(1) = j0 ---
        k0 = j0 - 1
        S_new_1 = 1 << k0  # Mask after using j0
        S2 = S_new_1 >> 1   # Mask for i=2 (tracks {2, 3, 4, 5})
        DP[2][S2] = 1

        # --- DP Transition: i = 2 to N ---
        for i in range(2, N + 1):
            for S in range(MAX_STATE):
                if DP[i][S] == 0:
                    continue

                current_count = DP[i][S]

                # Try p(i) = j = i + k, where k in {0, 1, 2, 3}
                for k in range(D):
                    j = i + k

                    # 1. Check Linear Constraint: j must be <= N for i < N.
                    # If i=N, j can wrap around (N+1, N+2, N+3) which map to 1, 2, 3.
                    if i < N and j > N:
                        continue

                    # 2. Check availability in S
                    if (S >> k) & 1 == 0:

                        # Calculate S_new: j is used
                        S_new = S | (1 << k)

                        # Calculate S_next for i+1: Shift right, losing bit 0 (status of i)
                        S_next = S_new >> 1

                        DP[i+1][S_next] += current_count

        # --- Final Closure Check: i = N to i = 1 (Wrap Around) ---
        # We look at DP[N+1][S], which tracks usage of {1, 2, 3, 4}

